import { useEffect, useRef, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { api, mediaUrl } from './endpoints';
import { useLang } from './i18n';
import { decodeEntities, isRichText } from '../../server/richtext';
import type { Message } from './types';

// Link preview card under a message: the network's own preview (Message.links) when present, otherwise
// one generated by klatchly (/api/preview, fetched server-side behind an SSRF guard). Fetched lazily,
// when the bubble comes into view; images only through /api/media (mxc) or /api/preview-img.

const URL_RE = /https?:\/\/[^\s<>"']+[^\s<>"'.,;:!?)\]]/g;
const HREF_RE = /<a\s[^>]*href="(https?:\/\/[^"]+)"/gi;
const MAX = 1;

export function messageLinks(m: Message): string[] {
  if (!m.text || m.isDeleted) return [];
  const found: string[] = [];
  if (isRichText(m.text)) {
    for (const x of m.text.matchAll(HREF_RE)) found.push(decodeEntities(x[1]!));
  } else found.push(...(m.text.match(URL_RE) ?? []));
  return [...new Set(found.filter((u) => !/^https:\/\/matrix\.to\//i.test(u)))].slice(0, MAX);
}

const host = (u: string) => {
  try {
    return new URL(u).hostname.replace(/^www\./, '');
  } catch {
    return '';
  }
};

function Card({ url, title, description, site, img }: { url: string; title: string; description?: string; site?: string; img?: string }) {
  const [imgOk, setImgOk] = useState(true);
  return (
    <a className="link-card" href={url} target="_blank" rel="noopener noreferrer nofollow" data-testid="link-preview">
      {img && imgOk && <img className="link-card-img" src={img} alt="" loading="lazy" decoding="async" onError={() => setImgOk(false)} />}
      <span className="link-card-text">
        <span className="link-card-site">{site || host(url)}</span>
        <span className="link-card-title">{title}</span>
        {description && <span className="link-card-desc">{description}</span>}
      </span>
    </a>
  );
}

function Generated({ url }: { url: string }) {
  const lang = useLang();
  const ref = useRef<HTMLDivElement>(null);
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || seen) return;
    const io = new IntersectionObserver((e) => e.some((x) => x.isIntersecting) && setSeen(true), { rootMargin: '200px' });
    io.observe(el);
    return () => io.disconnect();
  }, [seen]);
  const q = useQuery({ queryKey: ['preview', url, lang], queryFn: () => api.preview(url, lang), enabled: seen, staleTime: Infinity, gcTime: 3600_000, retry: 0 });
  const p = q.data;
  return (
    <div ref={ref} className="link-slot">
      {p?.title && <Card url={url} title={p.title} description={p.description} site={p.siteName} img={p.image} />}
    </div>
  );
}

export function LinkPreviews({ m }: { m: Message }) {
  const api = m.links?.find((l) => l.title && /^https?:\/\//i.test(l.url));
  if (api) {
    return <Card url={api.url} title={api.title!} description={api.summary} img={mediaUrl(api.img)} />;
  }
  const urls = messageLinks(m);
  if (!urls.length) return null;
  return (
    <>
      {urls.map((u) => (
        <Generated key={u} url={u} />
      ))}
    </>
  );
}
